# ruff: noqa
import asyncio
from google.adk.agents.callback_context import CallbackContext
from google.adk.models.llm_response import LlmResponse
from google.genai import types

from app.agent import root_agent
from app.a2ui_utils import a2ui_callback, _extract_a2ui_messages, _surface_is_renderable

print("Agent instruction length:", len(root_agent.instruction))
print("Agent after_model_callback:", root_agent.after_model_callback)

# Mock response with raw A2UI JSON as generated by gemini
sample_a2ui_text = """[
  {
    "beginRendering": {
      "root": "root_card",
      "surfaceId": "monstera_care"
    }
  },
  {
    "surfaceUpdate": {
      "surfaceId": "monstera_care",
      "components": [
        {
          "id": "root_card",
          "component": {
            "Card": {
              "child": "main_column"
            }
          }
        },
        {
          "id": "main_column",
          "component": {
            "Column": {
              "children": {
                "explicitList": ["title_text", "details_text"]
              }
            }
          }
        },
        {
          "id": "title_text",
          "component": {
            "Text": {
              "text": {"literalString": "Monstera Deliciosa Care Guide"},
              "usageHint": "h1"
            }
          }
        },
        {
          "id": "details_text",
          "component": {
            "Text": {
              "text": {"literalString": "Water every 7 days. Prefers bright indirect light."},
              "usageHint": "body"
            }
          }
        }
      ]
    }
  }
]"""

mock_response = LlmResponse(
    content=types.Content(
        role="model",
        parts=[types.Part(text=sample_a2ui_text)]
    )
)

msgs = _extract_a2ui_messages(sample_a2ui_text)
print("Extracted A2UI messages count:", len(msgs))
print("Is renderable:", _surface_is_renderable(msgs))

res = a2ui_callback(None, mock_response)
print("Callback returned response:", res is not None)
if res:
    print("Custom metadata:", res.custom_metadata)
    print("Parts count:", len(res.content.parts))
    print("Part 0 inline data mime:", res.content.parts[0].inline_data.mime_type)
    print("Part 0 blob sample:", res.content.parts[0].inline_data.data[:100])
